      const a=2+paRand(8),b=2+paRand(8),plus=Math.random()<.5,ans=plus?a+b:a*b;
      const q=paEl('div','pa-question',a+(plus?' + ':' × ')+b);
      const wrong=new Set();while(wrong.size<3){const v=ans+(paRand(11)-5);if(v!==ans&&v>0)wrong.add(v);}
      const grid=paEl('div','pa-answers');
